def choose_move(observation):
    o = observation if isinstance(observation, dict) else {}
    w = int(o.get("grid_width", 0) or 0)
    h = int(o.get("grid_height", 0) or 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return 0, 0
        return 0, 0

    sp = pos(o.get("self_position", (0, 0)))
    op = pos(o.get("opponent_position", (0, 0)))

    resources = o.get("resources", []) or []
    obstacles = o.get("obstacles", []) or []
    blocked = set()
    for p in obstacles:
        x, y = pos(p)
        blocked.add((x, y))

    sx, sy = sp
    ox, oy = op

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def valid(dx, dy):
        nx, ny = sx + dx, sy + dy
        if w > 0 and (nx < 0 or nx >= w):
            return False
        if h > 0 and (ny < 0 or ny >= h):
            return False
        if (nx, ny) in blocked:
            return False
        return True

    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    target = None
    best_d = None
    for p in resources:
        x, y = pos(p)
        d = manhattan((sx, sy), (x, y))
        if best_d is None or d < best_d or (d == best_d and (x, y) < target):
            best_d = d
            target = (x, y)

    cx = (w - 1) // 2 if w > 0 else sx
    cy = (h - 1) // 2 if h > 0 else sy

    if target is not None:
        tx, ty = target
        # If enemy is very close, prefer safety over direct collection.
        if manhattan((sx, sy), (ox, oy)) <= 2:
            tx = sx + (sx - ox)
            ty = sy + (sy - oy)
