        dy = clamp_step(ty - sy)
        cand = [(dx, dy), (dx, 0), (0, dy), (dx, -dy), (-dx, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
    else:
        dist_op = manhattan((sx, sy), (ox, oy))
        if dist_op <= 2:
            tx = sx + (sx - ox)
            ty = sy + (sy - oy)
        else:
            tx, ty = cx, cy
        dx = clamp_step(tx - sx)
        dy = clamp_step(ty - sy)
        cand = [(dx, dy), (dx, 0), (0, dy), (dx, -dy), (-dx, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]

    seen = set()
    for dx, dy in cand:
        if (dx, dy) in seen:
            continue
        seen.add((dx, dy))
        if valid(dx, dy):
            return [dx, dy]

    return [0, 0]

